/**
 * Request a purge of every feedback record in a dataset.
 *
 * There is deliberately no optimistic update and nothing to invalidate: the purge runs in the
 * background on the Hub and this screen lists datasets, not records, so there is no local state that
 * "records are gone" would be true of yet. Success here means *accepted*.
 */
export const usePurgeFeedbackDataset = () =>
  useMutation({
    mutationFn: (variables: { datasetId: string }) => purgeFeedbackDataset(variables.datasetId),
  });

"use client";

import { useQuery } from "@tanstack/react-query";
import { getEnrichmentStatus } from "../lib/api-client";
import { ENRICHMENT_POLL_INTERVAL_MS, totalPendingEnrichments } from "../lib/enrichment";
import { enrichmentStatusKeys } from "../lib/query";

/**
 * Enrichment progress for a workspace's feedback directories — feeds the indicator above the records
 * table. The route is a live query on the Hub, so there is no staleness to work around; it self-polls
 * only while work is outstanding and stops at zero (or when the Hub is unavailable), the same way the
 * taxonomy fields query polls while embeddings catch up.
 */
export const useEnrichmentStatus = ({
  workspaceId,
  enabled = true,
}: Readonly<{ workspaceId: string; enabled?: boolean }>) =>
  useQuery({
    queryKey: enrichmentStatusKeys.status(workspaceId),
    enabled: enabled && workspaceId.length > 0,
    queryFn: ({ signal }) => getEnrichmentStatus({ workspaceId, signal }),
    refetchInterval: (query) => {
      const data = query.state.data;
      if (!data || data.unavailable) {
        return false;
      }
      return totalPendingEnrichments(data.enrichments) > 0 ? ENRICHMENT_POLL_INTERVAL_MS : false;
    },
  });

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the internal feedback-datasets routes. Mutations use an explicit timeout;
 * every call throws a parsed `V3ApiError` on a non-2xx response.
 */

const BASE_PATH = "/api/internal/feedback-datasets";
const MUTATION_TIMEOUT_MS = 15_000;

export type TPurgeFeedbackDatasetResponse = {
  datasetId: string;
  status: string;
};

/**
 * Ask the Hub to delete every feedback record in a dataset.
 *
 * Resolves once the purge has been *accepted*, not once it has run — the Hub performs it in the
 * background, so there is no deleted count and the records are still present when this returns.
 */
export async function purgeFeedbackDataset(datasetId: string): Promise<TPurgeFeedbackDatasetResponse> {
  const response = await fetch(`${BASE_PATH}/${encodeURIComponent(datasetId)}/purge`, {
    method: "POST",
    signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  return ((await response.json()) as { data: TPurgeFeedbackDatasetResponse }).data;
}

