/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate — replace the secret for an existing API key.
 *
 * Thin adapter delegating to the framework-agnostic handler in the api-key lib.
 */
import { z } from "zod";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { successResponse } from "@/app/api/v3/lib/response";
import { ZId } from "@formbricks/types/common";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";

const ZV3ApiKeyIdParams = z.strictObject({
  apiKeyId: ZId,
});
type TV3ApiKeyIdParams = z.infer<typeof ZV3ApiKeyIdParams>;

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "rotated",
  targetType: "apiKey",
  schemas: { params: ZV3ApiKeyIdParams, query: ZV3EmptyQuery },
  handler: async ({ parsedInput, authentication, auditLog, requestId, instance }) => {
    const sessionUserId = getV3SessionUserId(authentication);
    if (!sessionUserId) {
      throw new Error("Session user is required for this operation");
    }

    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.params.apiKeyId);
    await assertCan({ type: "user", id: sessionUserId }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.params.apiKeyId,
    });

    const result = await rotateApiKey(parsedInput.params.apiKeyId, sessionUserId);

    return successResponse(result, { requestId });
  },
});

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the api-keys v3 routes.
 * Every call throws a parsed `V3ApiError` on a non-2xx response.
 */

const BASE_PATH = "/api/v3/api-keys";
const MUTATION_TIMEOUT_MS = 15_000;

export type TRotateApiKeyResponse = {
  id: string;
  label: string;
  createdAt: string;
  lastUsedAt: string | null;
  organizationAccess: unknown;
  apiKeyWorkspaces: Array<{ workspaceId: string; permission: string }>;
  actualKey: string;
};

/**
 * Rotate an existing API key, generating a new secret while preserving
 * the key's label, organization access, and workspace permissions.
 */
export async function rotateApiKey(apiKeyId: string): Promise<TRotateApiKeyResponse> {
  const response = await fetch(
    `${BASE_PATH}/${encodeURIComponent(apiKeyId)}/rotate`,
    {
      method: "POST",
      signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
    }
  );

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  return ((await response.json()) as { data: TRotateApiKeyResponse }).data;
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { rotateApiKey } from "../lib/api-client";

/**
 * Query key factory for api-keys data.
 */
export const apiKeyKeys = {
  all: ["api-keys"] as const,
  list: (organizationId: string) => [...apiKeyKeys.all, organizationId] as const,
};

/**
 * Hook to rotate an API key.
 *
 * On success, the caller should invalidate the api-keys query so the list
 * picks up the cleared `lastUsedAt` (rotation resets usage tracking).
 */
export const useRotateApiKey = (organizationId: string) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (variables: { apiKeyId: string }) => rotateApiKey(variables.apiKeyId),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: apiKeyKeys.list(organizationId) });
    },
  });
};

